INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-close-to-open-edge', 'close-to-open-edge', 'Close-to-Open Edge', 'Splits each session into the overnight leg (previous close to open) and the intraday leg (open to close) and compounds each. Validated 2026-10-29 against the third-party Open Alpha Lab study 01 (SPY 1993-01-29 to 2026-06-01): overnight +1,185.45% vs +1,185%, intraday +34.21% vs +34%, within 1 percentage point. The reference finds the effect real but mostly beta below trading costs. Spec: docs/specs/strategies/close-to-open-edge.md. Research only.', 'python', 'backtested', 'services/research/strategies/published_rules.py', '["instagram-carousel","overnight","daily","validated"]'::jsonb, 'Entry timing', '[]'::jsonb),
  ('strategy-seed-pairs-trading-divergence', 'pairs-trading-divergence', 'Pairs Trading Divergence', 'Chan (2008) example 3.6: GLD/GDX spread with a no-intercept hedge ratio from the first 252 days; long the spread at z <= -2, short at z >= 2, flat at |z| <= 1, using training-set mean and deviation. Validated 2026-10-29 on the author''s data files: training Sharpe 2.33 vs about 2.3, test Sharpe 1.51 vs about 1.5. Shorts one leg; not tradable under the options-only rule. Spec: docs/specs/strategies/pairs-trading-divergence.md. Research only.', 'python', 'backtested', 'services/research/strategies/published_rules.py', '["instagram-carousel","pairs","mean-reversion","daily","validated"]'::jsonb, 'Relative value', '[]'::jsonb),
  ('strategy-seed-volatility-compression-breakout', 'volatility-compression-breakout', 'Volatility Compression Breakout (NR7)', 'Crabel NR7: the narrowest high-low range of 7 sessions, then a next-day breakout of that bar''s high or low, held to the close. Validated 2026-10-29 against the third-party Open Alpha Lab study 190 (SPY 2000-2026): 1,036 vs 1,035 NR7 days, range ratio 0.911 vs 0.910, breakout mean +4.9 vs +5.4 bps. The reference finds no range expansion and about zero edge on SPY after costs. Spec: docs/specs/strategies/volatility-compression-breakout.md. Research only.', 'python', 'backtested', 'services/research/strategies/published_rules.py', '["instagram-carousel","breakout","volatility","daily","validated"]'::jsonb, 'Entry timing', '[]'::jsonb),
  ('strategy-seed-zscore-mean-reversion', 'zscore-mean-reversion', 'Z-Score Mean Reversion', 'Buys the next open after the close first falls below z = -2 (20-day mean and sample deviation, the lower Bollinger band) and exits at the close 20 sessions later. Validated 2026-10-29 against the third-party Open Alpha Lab study 104 (six US symbols, 2005-2026): 811 trades and +193.09 bps mean, matching exactly. The reference finds most of the return is market drift (random entries earn +141 bps). Spec: docs/specs/strategies/zscore-mean-reversion.md. Research only.', 'python', 'backtested', 'services/research/strategies/published_rules.py', '["instagram-carousel","mean-reversion","bollinger","daily","validated"]'::jsonb, 'Entry timing', '[]'::jsonb)
ON CONFLICT ("slug") DO NOTHING;
